// Same rules as lib/quote.ts in the app.
const { items, prices } = $input.first().json.body;
const share = prices.buybackPercent / 100;
const lines = items.map((item, index) => {
  const category = prices.categories.find((c) => c.id === item.priceCategoryId);
  if (!category) {
    return { index, type: item.type, quantity: item.quantity, condition: item.condition, categoryName: 'No matching category', pricedOnSite: true, low: 0, high: 0 };
  }
  const factor = prices.conditionMultiplier[item.condition] * share * item.quantity;
  return { index, type: item.type, quantity: item.quantity, condition: item.condition, categoryName: category.name, pricedOnSite: false, low: Math.round(category.resaleLow * factor), high: Math.round(category.resaleHigh * factor) };
});
const sumLow = lines.reduce((s, l) => s + l.low, 0);
const sumHigh = lines.reduce((s, l) => s + l.high, 0);
return [{ json: {
  lines,
  buybackPercent: prices.buybackPercent,
  fee: prices.feeRupees,
  totalLow: Math.max(0, sumLow - prices.feeRupees),
  totalHigh: Math.max(0, sumHigh - prices.feeRupees),
  pricedOnSiteCount: lines.filter((l) => l.pricedOnSite).length,
} }];
